import pandas as pd


def run(inputs: dict) -> dict:
    dim = inputs['DIM_ACCOUNT'].copy()
    stg = inputs['STG_ACCOUNT'].copy()

    # Build per-account list of mutable version dicts.
    versions = {}
    for _, row in dim.iterrows():
        acc = row['account_id']
        end = row['eff_end_date']
        end = pd.NaT if pd.isna(end) else end
        versions.setdefault(acc, []).append({
            'plan': row['plan'],
            'eff_start_date': row['eff_start_date'],
            'eff_end_date': end,
            'is_current': row['is_current'],
        })

    stg_sorted = stg.sort_values(['account_id', 'update_date'], kind='mergesort')

    def plan_equal(p1, p2):
        n1 = pd.isna(p1)
        n2 = pd.isna(p2)
        if n1 and n2:
            return True
        if n1 != n2:
            return False
        return p1 == p2

    for _, s in stg_sorted.iterrows():
        acc = s['account_id']
        upd = s['update_date']
        splan = s['plan']

        vlist = versions.setdefault(acc, [])

        if len(vlist) == 0:
            vlist.append({
                'plan': splan,
                'eff_start_date': upd,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })
            continue

        # find covering version: start <= upd < end (end NULL == infinity)
        covering = None
        for v in vlist:
            start = v['eff_start_date']
            end = v['eff_end_date']
            if start <= upd and (pd.isna(end) or upd < end):
                covering = v
                break

        if covering is None:
            # earlier than the account's first version
            f = min(vlist, key=lambda v: v['eff_start_date'])
            vlist.append({
                'plan': splan,
                'eff_start_date': upd,
                'eff_end_date': f['eff_start_date'],
                'is_current': 0,
            })
        else:
            v = covering
            if plan_equal(v['plan'], splan):
                pass
            elif upd == v['eff_start_date']:
                v['plan'] = splan
            else:
                vlist.append({
                    'plan': splan,
                    'eff_start_date': upd,
                    'eff_end_date': v['eff_end_date'],
                    'is_current': v['is_current'],
                })
                v['eff_end_date'] = upd
                v['is_current'] = 0

    records = []
    for acc, vlist in versions.items():
        for v in vlist:
            records.append({
                'account_id': acc,
                'plan': v['plan'],
                'eff_start_date': v['eff_start_date'],
                'eff_end_date': v['eff_end_date'],
                'is_current': v['is_current'],
            })

    out = pd.DataFrame(
        records,
        columns=['account_id', 'plan', 'eff_start_date', 'eff_end_date', 'is_current'],
    )

    if len(out) > 0:
        out = out.sort_values(['account_id', 'eff_start_date'], kind='mergesort').reset_index(drop=True)
        acc_dtype = dim['account_id'].dtype if len(dim) > 0 else stg['account_id'].dtype
        out['account_id'] = out['account_id'].astype(acc_dtype)
        is_current_dtype = dim['is_current'].dtype if len(dim) > 0 else None
        if is_current_dtype is not None:
            out['is_current'] = out['is_current'].astype(is_current_dtype)
        else:
            out['is_current'] = out['is_current'].astype('int64')

    return {'dim_account_out': out}
